/**
 * Short sound effects: feedback on an answer (lessons and reviews), a finished unit, a new level.
 * The player factory is injected so the logic is testable without the native module;
 * feedbackSoundDevice.ts wires expo-audio. Sounds are generated by scripts/make-sounds.cjs.
 */

/** Heard after every answer, so the learner chooses among three of each. */
export const SUCCESS_SOUNDS = ['pop', 'chime', 'marimba'] as const;
export const ERROR_SOUNDS = ['thud', 'soft', 'glide'] as const;
export type SuccessSound = (typeof SUCCESS_SOUNDS)[number];
export type ErrorSound = (typeof ERROR_SOUNDS)[number];

export type SoundName = `success-${SuccessSound}` | `error-${ErrorSound}` | 'unit-complete' | 'level-up';

/** The least intrusive of each, since they repeat all through a lesson. */
export const DEFAULT_SUCCESS_SOUND: SuccessSound = 'pop';
export const DEFAULT_ERROR_SOUND: ErrorSound = 'thud';

/** The part of an expo-audio player used here. */
export interface SoundPlayer {
  volume: number;
  seekTo(seconds: number): Promise<void>;
  play(): void;
}

export interface FeedbackSounds {
  play(name: SoundName): void;
}

/** Quiet enough to sit under the interface, never startling. */
export const FEEDBACK_VOLUME = 0.7;

export function createFeedbackSounds(createPlayer: (name: SoundName) => SoundPlayer): FeedbackSounds {
  const players: Partial<Record<SoundName, SoundPlayer>> = {};
  return {
    play(name) {
      try {
        // Players are created on first use, then rewound so a quick second answer replays the sound.
        let player = players[name];
        if (!player) {
          player = createPlayer(name);
          player.volume = FEEDBACK_VOLUME;
          players[name] = player;
        }
        player.seekTo(0).catch(() => undefined);
        player.play();
      } catch {
        // A sound effect must never break an exercise (no audio output, browser autoplay rules…).
      }
    },
  };
}
